export var ALERT_PACKS = { en:EN, te:TE, hi:HI, kn:KN, ta:TA };

export function normLang(code){
  for(var i=0;i<ALERT_LANGS.length;i++){ if(ALERT_LANGS[i]==code) return code; }
  return "en";
}

function fill(str, vars){
  if(!vars) return str;
  return str.replace(/\{(\w+)\}/g, function(m, k){
    return vars[k]!=undefined ? String(vars[k]) : m;
  });
}

// Pure lookup used by the server and the voice layer (no React, no storage).
// Falls back to English, then to the supplied fallback; never returns a key.
export function alertText(lang, key, vars, fallback){
  var l = normLang(lang);
  var p = ALERT_PACKS[l];
  if(p[key]!=undefined && p[key]!="") return fill(p[key], vars);
  if(EN[key]!=undefined) return fill(EN[key], vars);
  return fallback ? fill(fallback, vars) : "";
}

export function hasAlertKey(lang, key){
  var p = ALERT_PACKS[normLang(lang)];
  return p[key]!=undefined && p[key]!="";
}
